definition.script:
import groovy.json.JsonSlurper;

@NonCPS
def parseBuildSpec(String text) {
    def spec = new JsonSlurper().parseText(text)
    def hashes = [:]
    for (build in spec.application) {
        hashes[build.project_job_git_key.toString()] = build.git_hash?.toString()
    }
    return [
        buildHashes: hashes,
        infrastructureGitHash: spec.infrastructure_git_hash?.toString(),
        bannerRolloutPresent: spec.banner_rollout != null,
        bannerDeployment: spec.banner_rollout?.deployment?.toString()
    ]
}

def retrieveBuildSpecId = ''
def build_hashes = [:]
def infrastructure_git_hash
def targetStack
def pipelineBuildId
def bannerRolloutPresent = false
def bannerForward = false
def bannerDeployment
def bannerRolloutTupleSha = ''
def bannerRolloutRunId = ''
def validatedArtifactBucket = ''

pipeline {
  agent any

  environment {
    SOURCE_SCRIPTS_FOLDER = "${JENKINS_HOME}/workspace/Bash_Functions/"
  }

  stages {
    stage('Verify Supported Banner Entrypoint') {
      steps {
        script {
          def causes = currentBuild.getBuildCauses('hudson.model.Cause$UpstreamCause')
          if (params.MIGRATIONS_COMPLETED_UPSTREAM) {
            if (causes.size() != 1 || causes[0].upstreamProject != 'Deployment Pipeline') {
              error('MIGRATIONS_COMPLETED_UPSTREAM requires the exact Deployment Pipeline upstream run')
            }
          }
          bannerRolloutRunId = "combined-${env.BUILD_NUMBER}"
        }
      }
    }

    stage('Retrieve Build Spec') {
      steps {
        script {
          def result = build job: 'Retrieve Build Spec', parameters: [
            [$class: 'StringParameterValue', name: 'RELEASE_CONTROL_BRANCH', value: RELEASE_CONTROL_BRANCH]
          ]
          retrieveBuildSpecId = result.number
        }
        script {
          copyArtifacts filter: '*', projectName: 'Retrieve Build Spec', selector: specific("" + retrieveBuildSpecId)
          sh 'cat build-spec.json'
          sh 'cat pipeline_git_commit.txt'
          def parsedBuildSpec = parseBuildSpec(readFile('build-spec.json'))
          build_hashes = parsedBuildSpec.buildHashes
          pipelineBuildId = readFile('pipeline_git_commit.txt').trim()
          infrastructure_git_hash = parsedBuildSpec.infrastructureGitHash
          bannerDeployment = parsedBuildSpec.bannerDeployment
          bannerRolloutPresent = parsedBuildSpec.bannerRolloutPresent
          bannerForward = bannerRolloutPresent && params.BANNER_ROLLOUT_OPERATION == 'FORWARD'
          validatedArtifactBucket = String.valueOf(params.STACK_S3_BUCKET)
          if (bannerRolloutPresent) {
            if (!(bannerDeployment in ['BDC', 'AIM-AHEAD'])) {
              error("Unsupported banner rollout deployment: ${bannerDeployment}")
            }
            String requestedArtifactBucket = params.STACK_S3_BUCKET?.toString()
            String controllerArtifactBucket = env.stack_s3_bucket?.toString()
            if (!requestedArtifactBucket || requestedArtifactBucket != requestedArtifactBucket.trim() ||
                    !controllerArtifactBucket || controllerArtifactBucket != controllerArtifactBucket.trim() ||
                    requestedArtifactBucket != controllerArtifactBucket) {
              error('Artifact bucket must be nonempty, canonical, and match the controller-bound artifact bucket')
            }
            validatedArtifactBucket = controllerArtifactBucket
            if (params.BANNER_ROLLOUT_OPERATION == 'FORWARD') {
              def upstreamCauses = currentBuild.getBuildCauses('hudson.model.Cause$UpstreamCause')
              if (!params.MIGRATIONS_COMPLETED_UPSTREAM || upstreamCauses.size() != 1 || upstreamCauses[0].upstreamProject != 'Deployment Pipeline') {
                error('Forward banner rollout requires the exact Deployment Pipeline upstream run')
              }
            }
            def aimAttestation = ''
            if (bannerDeployment == 'AIM-AHEAD') {
              if (!params.BANNER_AIM_ATTESTATION_JSON?.trim()) {
                error('AIM-AHEAD requires an exact Deployment Pipeline snapshot or standalone AIM-AHEAD NON_BANNER_COMPONENTS attestation parameter')
              }
              writeFile file: 'aim-ahead-operator-attestation.json', text: params.BANNER_AIM_ATTESTATION_JSON
              aimAttestation = '--attestation aim-ahead-operator-attestation.json'
            }
            withEnv([
              "BANNER_ARTIFACT_BUCKET=${validatedArtifactBucket}",
              "BANNER_CONTROLLER_ARTIFACT_BUCKET=${validatedArtifactBucket}"
            ]) {
              bannerRolloutTupleSha = sh(
                script: """python3 "${JENKINS_HOME}/banner-rollout/validate-banner-rollout.py" \
                  --deployment '${bannerDeployment}' \
                  --operation '${params.BANNER_ROLLOUT_OPERATION}' \
                  --build-spec build-spec.json \
                  --jenkins-source-commit '${env.JENKINS_SOURCE_COMMIT}' \
                  --release-control-commit '${pipelineBuildId}' \
                  --controller-deployment '${env.BANNER_CONTROLLER_DEPLOYMENT}' \
                  --artifact-bucket "\${BANNER_ARTIFACT_BUCKET}" \
                  --controller-artifact-bucket "\${BANNER_CONTROLLER_ARTIFACT_BUCKET}" \
                  ${aimAttestation} \
                  --run-database-migrations '${params.RUN_DATABASE_MIGRATIONS}' \
                  --include-api '${params.INCLUDE_PIC_SURE_API}' \
                  --include-psama '${params.INCLUDE_PIC_SURE_AUTH_MICRO_APP}' \
                  --include-frontend '${params.INCLUDE_PIC_SURE_FRONTEND}'""",
                returnStdout: true
              ).trim()
            }
          }
        }
      }
    }

    stage('Retrieve Stack') {
        steps {
            script {
                targetStack = sh(script: """
                bash -c '
                set +x

                if [ ! -d "$SOURCE_SCRIPTS_FOLDER" ]; then
                    echo "Error: Source folder does not exist: $SOURCE_SCRIPTS_FOLDER"
                    exit 1
                fi

                for script_file in "$SOURCE_SCRIPTS_FOLDER"*.sh; do
                    chmod +x "\$script_file"
                    if [ -f "\$script_file" ] && [ -x "\$script_file" ]; then
                        . "\$script_file"  # Use dot (.) instead of `source`
                    fi
                done

                # The PIC-SURE Pipeline is always used to deploy to staging.
                get_stack \"${TARGET_STACK}\"
                '
                """, returnStdout: true).trim()

                println "TARGET_STACK: $targetStack"
            }
        }
    }

    stage('Database Migrations (once)') {
      when {
        expression { return params.RUN_DATABASE_MIGRATIONS && !params.MIGRATIONS_COMPLETED_UPSTREAM && (params.INCLUDE_PIC_SURE_API || params.INCLUDE_PIC_SURE_AUTH_MICRO_APP || params.INCLUDE_PIC_SURE_VISUALIZATION) }
      }
      steps {
        script {
          lock('shared-db') {
            echo "Running migrations with infrastructure_git_hash=${infrastructure_git_hash}"
            build job: 'Database Migrations', parameters: [
              [$class: 'StringParameterValue', name: 'infrastructure_git_hash', value: infrastructure_git_hash]
            ]
          }
        }
      }
    }


    stage('Monorepo Build and Package') {
      steps {
        script {
          lock("stack-${targetStack}") {
            def needsMonorepo = params.INCLUDE_PIC_SURE_API || params.INCLUDE_PIC_SURE_HPDS_AUTH || params.INCLUDE_PIC_SURE_HPDS_OPEN || params.INCLUDE_PIC_SURE_AUTH_MICRO_APP || params.INCLUDE_PIC_SURE_VISUALIZATION || params.INCLUDE_PIC_SURE_DICTIONARY || params.INCLUDE_PIC_SURE_LOGGING
            if (needsMonorepo) {
              build job: 'PIC-SURE Maven Build', parameters: [
                [$class: 'StringParameterValue', name: 'git_hash', value: build_hashes['PSA']],
                [$class: 'StringParameterValue', name: 'TARGET_STACK', value: targetStack],
                [$class: 'StringParameterValue', name: 'pipeline_build_id', value: pipelineBuildId]
              ]
            }
            def imageParams = [
              [$class: 'StringParameterValue', name: 'TARGET_STACK', value: targetStack],
              [$class: 'StringParameterValue', name: 'pipeline_build_id', value: pipelineBuildId],
              [$class: 'StringParameterValue', name: 'S3_BUCKET_NAME', value: validatedArtifactBucket]
            ]
            def bannerImageParams = imageParams + [
              [$class: 'StringParameterValue', name: 'BANNER_ROLLOUT_RUN_ID', value: bannerForward ? bannerRolloutRunId : '']
            ]
            def branches = [:]
            if (params.INCLUDE_PIC_SURE_API) {
              branches['gateway']    = { build job: 'PIC-SURE Gateway Image', parameters: bannerImageParams }
              branches['operations'] = { build job: 'PIC-SURE Operations Service Image', parameters: bannerImageParams }
              branches['query']      = { build job: 'PIC-SURE HPDS Query Service Image', parameters: bannerImageParams }
            }
            if (params.INCLUDE_PIC_SURE_HPDS_AUTH || params.INCLUDE_PIC_SURE_HPDS_OPEN) { branches['hpds'] = { build job: 'PIC-SURE HPDS Image', parameters: imageParams } }
            if (params.INCLUDE_PIC_SURE_AUTH_MICRO_APP) { branches['psama'] = { build job: 'PIC-SURE Auth Micro App Image', parameters: bannerImageParams } }
            if (params.INCLUDE_PIC_SURE_VISUALIZATION)  { branches['visualization'] = { build job: 'PIC-SURE Visualization Image', parameters: imageParams } }
            if (params.INCLUDE_PIC_SURE_DICTIONARY)     { branches['dictionary'] = { build job: 'PIC-SURE Dictionary Image', parameters: imageParams } }
            if (params.INCLUDE_PIC_SURE_LOGGING)        { branches['logging'] = { build job: 'PIC-SURE Logging Image', parameters: imageParams } }
            if (params.INCLUDE_PIC_SURE_FRONTEND) {
              branches['frontend'] = {
                build job: 'PIC-SURE Frontend Build', parameters: [
                  [$class: 'StringParameterValue', name: 'TARGET_STACK', value: targetStack],
                  [$class: 'StringParameterValue', name: 'git_hash', value: build_hashes['PSF']],
                  [$class: 'StringParameterValue', name: 'S3_BUCKET_NAME', value: validatedArtifactBucket],
                  [$class: 'StringParameterValue', name: 'BANNER_ROLLOUT_RUN_ID', value: bannerForward ? bannerRolloutRunId : '']
                ]
              }
            }
            if (branches) { parallel branches }

            if (params.INCLUDE_PIC_SURE_VISUALIZATION) {
              build job: 'Render PIC-SURE Visualization Config Template', parameters: [
                [$class: 'StringParameterValue', name: 'INFRASTRUCTURE_GIT_HASH', value: infrastructure_git_hash],
                [$class: 'StringParameterValue', name: 'TARGET_STACK', value: targetStack]
              ]
            }

            def deployBranches = [:]
            deployBranches['banner_backend_then_frontend'] = {
              def shouldDeploy = params.INCLUDE_PIC_SURE_API || params.INCLUDE_PIC_SURE_AUTH_MICRO_APP || params.INCLUDE_PIC_SURE_DICTIONARY || params.INCLUDE_PIC_SURE_VISUALIZATION
              if (shouldDeploy) {
                build job: 'PIC-SURE Wildfly Stack Deploy', parameters: [
                  [$class: 'StringParameterValue', name: 'TARGET_STACK', value: targetStack],
                  [$class: 'StringParameterValue', name: 'S3_BUCKET_NAME', value: validatedArtifactBucket],
                  [$class: 'StringParameterValue', name: 'DATASET_S3_OBJECT_KEY', value: String.valueOf(params.DATASET_S3_OBJECT_KEY)],
                  [$class: 'BooleanParameterValue', name: 'DEPLOY_GATEWAY', value: params.INCLUDE_PIC_SURE_API],
                  [$class: 'BooleanParameterValue', name: 'DEPLOY_OPERATIONS', value: params.INCLUDE_PIC_SURE_API],
                  [$class: 'BooleanParameterValue', name: 'DEPLOY_QUERY', value: params.INCLUDE_PIC_SURE_API],
                  [$class: 'BooleanParameterValue', name: 'DEPLOY_PSAMA', value: params.INCLUDE_PIC_SURE_AUTH_MICRO_APP],
                  [$class: 'BooleanParameterValue', name: 'DEPLOY_DICTIONARY', value: params.INCLUDE_PIC_SURE_DICTIONARY],
                  [$class: 'BooleanParameterValue', name: 'DEPLOY_VISUALIZATION', value: params.INCLUDE_PIC_SURE_VISUALIZATION],
                  [$class: 'BooleanParameterValue', name: 'BANNER_ROLLOUT', value: bannerForward],
                  [$class: 'StringParameterValue', name: 'BANNER_ROLLOUT_DEPLOYMENT', value: bannerDeployment ?: ''],
                  [$class: 'StringParameterValue', name: 'BANNER_ROLLOUT_TUPLE_SHA256', value: bannerRolloutTupleSha],
                  [$class: 'StringParameterValue', name: 'BANNER_ROLLOUT_RUN_ID', value: bannerForward ? bannerRolloutRunId : '']
                ]
              } else {
                echo 'Skipping Wildfly Stack Deploy (no wildfly-host components selected)'
              }
              if (params.INCLUDE_PIC_SURE_FRONTEND) {
                build job: 'PIC-SURE Frontend Deploy', parameters: [
                  [$class: 'StringParameterValue', name: 'TARGET_STACK', value: targetStack],
                  [$class: 'StringParameterValue', name: 'S3_BUCKET_NAME', value: validatedArtifactBucket],
                  [$class: 'BooleanParameterValue', name: 'BANNER_ROLLOUT', value: bannerForward],
                  [$class: 'StringParameterValue', name: 'BANNER_ROLLOUT_DEPLOYMENT', value: bannerDeployment ?: ''],
                  [$class: 'StringParameterValue', name: 'BANNER_ROLLOUT_TUPLE_SHA256', value: bannerRolloutTupleSha],
                  [$class: 'StringParameterValue', name: 'BANNER_BACKEND_HEALTH_RECEIPT', value: bannerForward ? bannerRolloutRunId : ''],
                  [$class: 'StringParameterValue', name: 'BANNER_ROLLOUT_RUN_ID', value: bannerForward ? bannerRolloutRunId : '']
                ]
              } else {
                echo 'Skipping PIC-SURE Frontend Deploy'
              }
            }
            deployBranches['hpds_auth_deploy'] = {
                if (params.INCLUDE_PIC_SURE_HPDS_AUTH) {
                  build job: 'PIC-SURE HPDS Auth Deploy', parameters: [
                    [$class: 'StringParameterValue', name: 'TARGET_STACK', value: targetStack],
                    [$class: 'StringParameterValue', name: 'S3_BUCKET_NAME', value: validatedArtifactBucket],
                    [$class: 'StringParameterValue', name: 'DATA_S3_OBJECT_KEY', value: String.valueOf(params.DATA_S3_OBJECT_KEY)],
                    [$class: 'StringParameterValue', name: 'GENOMIC_DATASET_S3_OBJECT_KEY', value: String.valueOf(params.GENOMIC_DATASET_S3_OBJECT_KEY)]
                  ]
                } else {
                  echo 'Skipping HPDS Auth Deploy'
                }
            }
            deployBranches['hpds_open_deploy'] = {
                if (params.INCLUDE_PIC_SURE_HPDS_OPEN) {
                  build job: 'PIC-SURE HPDS Open Deploy', parameters: [
                    [$class: 'StringParameterValue', name: 'TARGET_STACK', value: targetStack],
                    [$class: 'StringParameterValue', name: 'S3_BUCKET_NAME', value: validatedArtifactBucket],
                    [$class: 'StringParameterValue', name: 'DESTIGMATIZED_DATASET_S3_OBJECT_KEY', value: String.valueOf(params.DESTIGMATIZED_DATASET_S3_OBJECT_KEY)]
                  ]
                } else {
                  echo 'Skipping HPDS Open Deploy'
                }
            }
            deployBranches['logging_deploy'] = {
                if (params.INCLUDE_PIC_SURE_LOGGING) {
                  build job: 'PIC-SURE Logging Deploy', parameters: [
                    [$class: 'StringParameterValue', name: 'TARGET_STACK', value: targetStack]
                  ]
                } else {
                  echo 'Skipping PIC-SURE Logging Deploy'
                }
            }
            parallel deployBranches
          }
        }
      }
    }

  }
}
